private fun uniffiCheckContractApiVersion(lib: IntegrityCheckingUniffiLib) {
    // Get the bindings contract version from our ComponentInterface
    val bindings_contract_version = 30
    // Get the scaffolding contract version by calling the into the dylib
    val scaffolding_contract_version = lib.ffi_flowww_ffi_uniffi_contract_version()
    if (bindings_contract_version != scaffolding_contract_version) {
        throw RuntimeException("UniFFI contract version mismatch: try cleaning and rebuilding your project")
    }
}
@Suppress("UNUSED_PARAMETER")
private fun uniffiCheckApiChecksums(lib: IntegrityCheckingUniffiLib) {
    if ((lib.uniffi_flowww_ffi_checksum_method_flowwweventlistener_on_event() and 0xFFFF) != 4608) {
        throw RuntimeException("UniFFI API checksum mismatch: try cleaning and rebuilding your project")
    }
    if ((lib.uniffi_flowww_ffi_checksum_method_flowwwnode_active_pairing() and 0xFFFF) != 29929) {
        throw RuntimeException("UniFFI API checksum mismatch: try cleaning and rebuilding your project")
    }
    if ((lib.uniffi_flowww_ffi_checksum_method_flowwwnode_add_listener() and 0xFFFF) != 17795) {
        throw RuntimeException("UniFFI API checksum mismatch: try cleaning and rebuilding your project")
    }
    if ((lib.uniffi_flowww_ffi_checksum_method_flowwwnode_cancel_pairing() and 0xFFFF) != 136) {
        throw RuntimeException("UniFFI API checksum mismatch: try cleaning and rebuilding your project")
    }
    if ((lib.uniffi_flowww_ffi_checksum_method_flowwwnode_cancel_transfer() and 0xFFFF) != 19436) {
        throw RuntimeException("UniFFI API checksum mismatch: try cleaning and rebuilding your project")
    }
    if ((lib.uniffi_flowww_ffi_checksum_method_flowwwnode_is_running() and 0xFFFF) != 56832) {
