/**
 * Events pushed to Kotlin listeners.
 *
 * Mirrors [`flowww_node::NodeEvent`]; the spatial-relay variants are not
 * forwarded (spatial is out of scope for this boundary).
 */
sealed class FlowwwEvent {
    
    /**
     * The node started and its listener is bound.
     */
    object NodeStarted : FlowwwEvent()
    
    
    /**
     * The node shut down.
     */
    object NodeStopped : FlowwwEvent()
    
    
    /**
     * A peer appeared on the local network.
     */
    data class PeerFound(
        val `peer`: com.flowww.android.uniffi.PeerDto) : FlowwwEvent()
        
    {
        

        companion object
    }
    
    /**
     * A peer left the local network.
     */
    data class PeerLost(
        val `deviceId`: kotlin.String) : FlowwwEvent()
        
    {
        

        companion object
    }
    
    /**
     * A pairing session started. Render `uri` as a QR code.
     */
    data class PairingStarted(
        val `uri`: kotlin.String, 
        val `endpoint`: kotlin.String, 
        val `expiresAt`: kotlin.ULong) : FlowwwEvent()
        
    {
        

        companion object
    }
    
    /**
     * Pairing completed and the peer is pinned in the trust store.
     */
    data class PairingCompleted(
        val `device`: com.flowww.android.uniffi.DeviceDto) : FlowwwEvent()
        
    {
        

        companion object
    }
    
    /**
     * Pairing failed (timeout, bad URI, mismatch, cancelled, ...).
     */
    data class PairingFailed(
        val `reason`: kotlin.String) : FlowwwEvent()
        
    {
        

        companion object
    }
    
    /**
     * Another device offered us content; show approval UI.
     */
    data class OfferReceived(
        val `offer`: com.flowww.android.uniffi.PendingOfferDto) : FlowwwEvent()
        
    {
        

        companion object
    }
    
    /**
     * An offer was answered or timed out.
     */
    data class OfferClosed(
        val `transferId`: kotlin.String) : FlowwwEvent()
        
    {
        

        companion object
    }
    
    /**
     * Transfer lifecycle snapshot; emitted per chunk and at terminal state.
     */
    data class TransferUpdated(
        val `record`: com.flowww.android.uniffi.TransferRecordDto) : FlowwwEvent()
        
    {
        

        companion object
    }
    
    /**
     * Non-fatal error worth showing in diagnostics.
     */
    data class Error(
        val `message`: kotlin.String) : FlowwwEvent()
        
    {
        

        companion object
    }
    

    

    
    


    companion object
}

