 * @suppress
 */
public object FfiConverterTypeFlowwwEvent : FfiConverterRustBuffer<FlowwwEvent>{
    override fun read(buf: ByteBuffer): FlowwwEvent {
        return when(buf.getInt()) {
            1 -> FlowwwEvent.NodeStarted
            2 -> FlowwwEvent.NodeStopped
            3 -> FlowwwEvent.PeerFound(
                FfiConverterTypePeerDto.read(buf),
                )
            4 -> FlowwwEvent.PeerLost(
                FfiConverterString.read(buf),
                )
            5 -> FlowwwEvent.PairingStarted(
                FfiConverterString.read(buf),
                FfiConverterString.read(buf),
                FfiConverterULong.read(buf),
                )
            6 -> FlowwwEvent.PairingCompleted(
                FfiConverterTypeDeviceDto.read(buf),
                )
            7 -> FlowwwEvent.PairingFailed(
                FfiConverterString.read(buf),
                )
            8 -> FlowwwEvent.OfferReceived(
                FfiConverterTypePendingOfferDto.read(buf),
                )
            9 -> FlowwwEvent.OfferClosed(
                FfiConverterString.read(buf),
                )
            10 -> FlowwwEvent.TransferUpdated(
                FfiConverterTypeTransferRecordDto.read(buf),
                )
            11 -> FlowwwEvent.Error(
                FfiConverterString.read(buf),
                )
            else -> throw RuntimeException("invalid enum value, something is very wrong!!")
        }
    }

    override fun allocationSize(value: FlowwwEvent): ULong = when(value) {
        is FlowwwEvent.NodeStarted -> {
            // Add the size for the Int that specifies the variant plus the size needed for all fields
            (
                4UL
            )
        }
        is FlowwwEvent.NodeStopped -> {
            // Add the size for the Int that specifies the variant plus the size needed for all fields
            (
                4UL
            )
        }
        is FlowwwEvent.PeerFound -> {
            // Add the size for the Int that specifies the variant plus the size needed for all fields
            (
                4UL
                + FfiConverterTypePeerDto.allocationSize(value.`peer`)
            )
        }
        is FlowwwEvent.PeerLost -> {
            // Add the size for the Int that specifies the variant plus the size needed for all fields
            (
                4UL
                + FfiConverterString.allocationSize(value.`deviceId`)
            )
        }
        is FlowwwEvent.PairingStarted -> {
            // Add the size for the Int that specifies the variant plus the size needed for all fields
            (
                4UL
                + FfiConverterString.allocationSize(value.`uri`)
                + FfiConverterString.allocationSize(value.`endpoint`)
                + FfiConverterULong.allocationSize(value.`expiresAt`)
            )
        }
        is FlowwwEvent.PairingCompleted -> {
            // Add the size for the Int that specifies the variant plus the size needed for all fields
            (
                4UL
                + FfiConverterTypeDeviceDto.allocationSize(value.`device`)
            )
        }
        is FlowwwEvent.PairingFailed -> {
            // Add the size for the Int that specifies the variant plus the size needed for all fields
            (
                4UL
                + FfiConverterString.allocationSize(value.`reason`)
            )
        }
        is FlowwwEvent.OfferReceived -> {
            // Add the size for the Int that specifies the variant plus the size needed for all fields
            (
                4UL
                + FfiConverterTypePendingOfferDto.allocationSize(value.`offer`)
            )
        }
        is FlowwwEvent.OfferClosed -> {
            // Add the size for the Int that specifies the variant plus the size needed for all fields
            (
                4UL
                + FfiConverterString.allocationSize(value.`transferId`)
            )
        }
        is FlowwwEvent.TransferUpdated -> {
            // Add the size for the Int that specifies the variant plus the size needed for all fields
            (
                4UL
                + FfiConverterTypeTransferRecordDto.allocationSize(value.`record`)
            )
        }
        is FlowwwEvent.Error -> {
            // Add the size for the Int that specifies the variant plus the size needed for all fields
            (
                4UL
                + FfiConverterString.allocationSize(value.`message`)
            )
        }
    }

    override fun write(value: FlowwwEvent, buf: ByteBuffer) {
        when(value) {
            is FlowwwEvent.NodeStarted -> {
                buf.putInt(1)
                Unit
            }
            is FlowwwEvent.NodeStopped -> {
                buf.putInt(2)
                Unit
            }
            is FlowwwEvent.PeerFound -> {
                buf.putInt(3)
                FfiConverterTypePeerDto.write(value.`peer`, buf)
                Unit
            }
            is FlowwwEvent.PeerLost -> {
                buf.putInt(4)
                FfiConverterString.write(value.`deviceId`, buf)
                Unit
            }
            is FlowwwEvent.PairingStarted -> {
                buf.putInt(5)
                FfiConverterString.write(value.`uri`, buf)
                FfiConverterString.write(value.`endpoint`, buf)
                FfiConverterULong.write(value.`expiresAt`, buf)
                Unit
            }
            is FlowwwEvent.PairingCompleted -> {
                buf.putInt(6)
                FfiConverterTypeDeviceDto.write(value.`device`, buf)
                Unit
            }
            is FlowwwEvent.PairingFailed -> {
                buf.putInt(7)
                FfiConverterString.write(value.`reason`, buf)
                Unit
            }
            is FlowwwEvent.OfferReceived -> {
                buf.putInt(8)
                FfiConverterTypePendingOfferDto.write(value.`offer`, buf)
                Unit
            }
            is FlowwwEvent.OfferClosed -> {
                buf.putInt(9)
                FfiConverterString.write(value.`transferId`, buf)
                Unit
            }
            is FlowwwEvent.TransferUpdated -> {
                buf.putInt(10)
                FfiConverterTypeTransferRecordDto.write(value.`record`, buf)
                Unit
            }
            is FlowwwEvent.Error -> {
                buf.putInt(11)
                FfiConverterString.write(value.`message`, buf)
                Unit
            }
        }.let { /* this makes the `when` an expression, which ensures it is exhaustive */ }
    }
